#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/posix/fcntl.h>
#include <zephyr/posix/unistd.h>
#include <zephyr/sys/fdtable.h>

/*
 * Custom object type for testing fdtable.
 * This struct is intentionally simple, as its purpose is just to
 * provide a unique kernel object type for fdtable to manage.
 */
struct test_fd_obj {
    int dummy;
}; /* Fix: Added missing semicolon here */

K_OBJ_TYPE_DEFINE(test_fd_obj_type, sizeof(struct test_fd_obj));

static struct test_fd_obj obj_a;
static struct test_fd_obj obj_b;
static struct test_fd_obj obj_c;

/*
 * Initialize a test_fd_obj.
 * This function is registered with the fdtable to be called when
 * an object of type test_fd_obj_type is closed.
 */
static void test_fd_obj_init(void *obj)
{
    struct test_fd_obj *test_obj = (struct test_fd_obj *)obj;

    /* Mark the object as initialized/open */
    test_obj->dummy = 1;
}

/*
 * Deinitialize a test_fd_obj.
 * This function is registered with the fdtable to be called when
 * an object of type test_fd_obj_type is closed.
 */
static void test_fd_obj_deinit(void *obj)
{
    struct test_fd_obj *test_obj = (struct test_fd_obj *)obj;

    /* Mark the object as deinitialized/closed */
    test_obj->dummy = 0;
}

/* Test case: Allocate and free file descriptors */
ZTEST(fdtable_tests, test_fdtable_alloc_free)
{
    int fd1, fd2, fd3;
    int ret;

    /* Allocate first FD */
    fd1 = z_fdtable_alloc(&test_fd_obj_type, &obj_a, test_fd_obj_init,
                          test_fd_obj_deinit);
    zassert_true(fd1 >= 0, "Failed to allocate FD1");
    zassert_equal(obj_a.dummy, 1, "obj_a not initialized");

    /* Allocate second FD */
    fd2 = z_fdtable_alloc(&test_fd_obj_type, &obj_b, test_fd_obj_init,
                          test_fd_obj_deinit);
    zassert_true(fd2 >= 0, "Failed to allocate FD2");
    zassert_equal(obj_b.dummy, 1, "obj_b not initialized");
    zassert_not_equal(fd1, fd2, "FD1 and FD2 are same");

    /* Allocate third FD */
    fd3 = z_fdtable_alloc(&test_fd_obj_type, &obj_c, test_fd_obj_init,
                          test_fd_obj_deinit);
    zassert_true(fd3 >= 0, "Failed to allocate FD3");
    zassert_equal(obj_c.dummy, 1, "obj_c not initialized");
    zassert_not_equal(fd1, fd3, "FD1 and FD3 are same");
    zassert_not_equal(fd2, fd3, "FD2 and FD3 are same");

    /* Free FDs */
    ret = z_fdtable_free(fd1);
    zassert_equal(ret, 0, "Failed to free FD1");
    zassert_equal(obj_a.dummy, 0, "obj_a not deinitialized");

    ret = z_fdtable_free(fd2);
    zassert_equal(ret, 0, "Failed to free FD2");
    zassert_equal(obj_b.dummy, 0, "obj_b not deinitialized");

    ret = z_fdtable_free(fd3);
    zassert_equal(ret, 0, "Failed to free FD3");
    zassert_equal(obj_c.dummy, 0, "obj_c not deinitialized");

    /* Try to free an invalid FD */
    ret = z_fdtable_free(-1);
    zassert_equal(ret, -EBADF, "Freeing invalid FD did not return EBADF");

    ret = z_fdtable_free(1000); /* Assuming 1000 is out of range */
    zassert_equal(ret, -EBADF, "Freeing out-of-range FD did not return EBADF");
}

/* Test case: Get and put file descriptor objects */
ZTEST(fdtable_tests, test_fdtable_get_put)
{
    int fd;
    void *obj_ptr;
    int ret;

    /* Allocate an FD */
    fd = z_fdtable_alloc(&test_fd_obj_type, &obj_a, test_fd_obj_init,
                          test_fd_obj_deinit);
    zassert_true(fd >= 0, "Failed to allocate FD");
    zassert_equal(obj_a.dummy, 1, "obj_a not initialized");

    /* Get the object associated with the FD */
    obj_ptr = z_fdtable_object_get(fd, &test_fd_obj_type);
    zassert_equal(obj_ptr, &obj_a, "Did not get correct object");

    /* Put the object (release reference) */
    z_fdtable_object_put(fd);

    /* Try to get with wrong type */
    obj_ptr = z_fdtable_object_get(fd, K_OBJ_TYPE_DEFINE_ID_k_sem); /* Use a different type */
    zassert_is_null(obj_ptr, "Got object with wrong type");

    /* Put the object (release reference) */
    z_fdtable_object_put(fd);

    /* Try to get an invalid FD */
    obj_ptr = z_fdtable_object_get(-1, &test_fd_obj_type);
    zassert_is_null(obj_ptr, "Got object for invalid FD");

    /* Put the object (release reference) */
    z_fdtable_object_put(-1);

    /* Free the FD */
    ret = z_fdtable_free(fd);
    zassert_equal(ret, 0, "Failed to free FD");
    zassert_equal(obj_a.dummy, 0, "obj_a not deinitialized");
}

/* Test case: Duplicate file descriptor (dup) */
ZTEST(fdtable_tests, test_fdtable_dup)
{
    int old_fd, new_fd;
    void *obj_ptr;
    int ret;

    /* Allocate an FD */
    old_fd = z_fdtable_alloc(&test_fd_obj_type, &obj_a, test_fd_obj_init,
                             test_fd_obj_deinit);
    zassert_true(old_fd >= 0, "Failed to allocate old_fd");
    zassert_equal(obj_a.dummy, 1, "obj_a not initialized");

    /* Duplicate the FD */
    new_fd = z_fdtable_dup(old_fd, 0); /* flags = 0 */
    zassert_true(new_fd >= 0, "Failed to duplicate FD");
    zassert_not_equal(old_fd, new_fd, "old_fd and new_fd are same");

    /* Verify both FDs point to the same object */
    obj_ptr = z_fdtable_object_get(old_fd, &test_fd_obj_type);
    zassert_equal(obj_ptr, &obj_a, "old_fd did not get correct object");
    z_fdtable_object_put(old_fd);

    obj_ptr = z_fdtable_object_get(new_fd, &test_fd_obj_type);
    zassert_equal(obj_ptr, &obj_a, "new_fd did not get correct object");
    z_fdtable_object_put(new_fd);

    /* Free both FDs */
    ret = z_fdtable_free(old_fd);
    zassert_equal(ret, 0, "Failed to free old_fd");
    /* obj_a should still be initialized as new_fd holds a reference */
    zassert_equal(obj_a.dummy, 1, "obj_a deinitialized prematurely");

    ret = z_fdtable_free(new_fd);
    zassert_equal(ret, 0, "Failed to free new_fd");
    /* Now obj_a should be deinitialized */
    zassert_equal(obj_a.dummy, 0, "obj_a not deinitialized");

    /* Test dup with invalid FD */
    new_fd = z_fdtable_dup(-1, 0);
    zassert_equal(new_fd, -EBADF, "Dup invalid FD did not return EBADF");
}

/* Test case: Duplicate file descriptor to a specific FD (dup2) */
ZTEST(fdtable_tests, test_fdtable_dup2)
{
    int old_fd, new_fd;
    void *obj_ptr;
    int ret;

    /* Allocate an FD */
    old_fd = z_fdtable_alloc(&test_fd_obj_type, &obj_a, test_fd_obj_init,
                             test_fd_obj_deinit);
    zassert_true(old_fd >= 0, "Failed to allocate old_fd");
    zassert_equal(obj_a.dummy, 1, "obj_a not initialized");

    /* Allocate another FD to be replaced by dup2 */
    new_fd = z_fdtable_alloc(&test_fd_obj_type, &obj_b, test_fd_obj_init,
                             test_fd_obj_deinit);
    zassert_true(new_fd >= 0, "Failed to allocate new_fd for replacement");
    zassert_equal(obj_b.dummy, 1, "obj_b not initialized");
    zassert_not_equal(old_fd, new_fd, "old_fd and new_fd are same initially");

    /* Duplicate old_fd to new_fd (replacing obj_b with obj_a) */
    ret = z_fdtable_dup2(old_fd, new_fd, 0); /* flags = 0 */
    zassert_equal(ret, new_fd, "Failed to dup2 FD");

    /* Verify new_fd now points to obj_a, and obj_b is deinitialized */
    obj_ptr = z_fdtable_object_get(new_fd, &test_fd_obj_type);
    zassert_equal(obj_ptr, &obj_a, "new_fd did not get correct object (obj_a)");
    z_fdtable_object_put(new_fd);
    zassert_equal(obj_b.dummy, 0, "obj_b not deinitialized after dup2");

    /* Verify old_fd still points to obj_a */
    obj_ptr = z_fdtable_object_get(old_fd, &test_fd_obj_type);
    zassert_equal(obj_ptr, &obj_a, "old_fd did not get correct object (obj_a)");
    z_fdtable_object_put(old_fd);

    /* Free both FDs */
    ret = z_fdtable_free(old_fd);
    zassert_equal(ret, 0, "Failed to free old_fd");
    zassert_equal(obj_a.dummy, 1, "obj_a deinitialized prematurely");

    ret = z_fdtable_free(new_fd);
    zassert_equal(ret, 0, "Failed to free new_fd");
    zassert_equal(obj_a.dummy, 0, "obj_a not deinitialized");

    /* Test dup2 with invalid old_fd */
    ret = z_fdtable_dup2(-1, 0, 0);
    zassert_equal(ret, -EBADF, "Dup2 invalid old_fd did not return EBADF");

    /* Test dup2 with invalid new_fd (out of range) */
    old_fd = z_fdtable_alloc(&test_fd_obj_type, &obj_a, test_fd_obj_init,
                             test_fd_obj_deinit);
    zassert_true(old_fd >= 0, "Failed to allocate old_fd for invalid new_fd test");
    ret = z_fdtable_dup2(old_fd, 1000, 0); /* Assuming 1000 is out of range */
    zassert_equal(ret, -EBADF, "Dup2 out-of-range new_fd did not return EBADF");
    z_fdtable_free(old_fd);
}

/* Test case: Close-on-exec flag (FD_CLOEXEC) */
ZTEST(fdtable_tests, test_fdtable_close_on_exec)
{
    int fd;
    int ret;
    int flags;

    /* Allocate an FD without CLOEXEC */
    fd = z_fdtable_alloc(&test_fd_obj_type, &obj_a, test_fd_obj_init,
                          test_fd_obj_deinit);
    zassert_true(fd >= 0, "Failed to allocate FD");
    zassert_equal(obj_a.dummy, 1, "obj_a not initialized");

    /* Check initial flags (should not have CLOEXEC) */
    flags = z_fdtable_get_flags(fd);
    zassert_true(flags >= 0, "Failed to get flags");
    zassert_false(flags & FD_CLOEXEC, "FD_CLOEXEC unexpectedly set");

    /* Set CLOEXEC flag */
    ret = z_fdtable_set_flags(fd, FD_CLOEXEC);
    zassert_equal(ret, 0, "Failed to set flags");

    /* Check flags again (should have CLOEXEC) */
    flags = z_fdtable_get_flags(fd);
    zassert_true(flags >= 0, "Failed to get flags after setting");
    zassert_true(flags & FD_CLOEXEC, "FD_CLOEXEC not set");

    /* Clear CLOEXEC flag */
    ret = z_fdtable_set_flags(fd, 0); /* Clear all flags, including CLOEXEC */
    zassert_equal(ret, 0, "Failed to clear flags");

    /* Check flags again (should not have CLOEXEC) */
    flags = z_fdtable_get_flags(fd);
    zassert_true(flags >= 0, "Failed to get flags after clearing");
    zassert_false(flags & FD_CLOEXEC, "FD_CLOEXEC not cleared");

    /* Test with invalid FD */
    ret = z_fdtable_set_flags(-1, FD_CLOEXEC);
    zassert_equal(ret, -EBADF, "Set flags on invalid FD did not return EBADF");

    flags = z_fdtable_get_flags(-1);
    zassert_equal(flags, -EBADF, "Get flags on invalid FD did not return EBADF");

    /* Free the FD */
    ret = z_fdtable_free(fd);
    zassert_equal(ret, 0, "Failed to free FD");
    zassert_equal(obj_a.dummy, 0, "obj_a not deinitialized");
}

/* Test case: Check if FD is valid */
ZTEST(fdtable_tests, test_fdtable_is_valid)
{
    int fd;
    bool valid;

    /* Allocate an FD */
    fd = z_fdtable_alloc(&test_fd_obj_type, &obj_a, test_fd_obj_init,
                          test_fd_obj_deinit);
    zassert_true(fd >= 0, "Failed to allocate FD");

    /* Check if valid */
    valid = z_fdtable_is_valid(fd);
    zassert_true(valid, "Allocated FD reported as invalid");

    /* Check invalid FDs */
    valid = z_fdtable_is_valid(-1);
    zassert_false(valid, "Invalid FD reported as valid");

    valid = z_fdtable_is_valid(1000); /* Assuming 1000 is out of range */
    zassert_false(valid, "Out-of-range FD reported as valid");

    /* Free the FD */
    z_fdtable_free(fd);

    /* Check if valid after freeing */
    valid = z_fdtable_is_valid(fd);
    zassert_false(valid, "Freed FD reported as valid");
}

/* Test case: Get object type */
ZTEST(fdtable_tests, test_fdtable_get_obj_type)
{
    int fd;
    const struct k_obj_type *type;

    /* Allocate an FD */
    fd = z_fdtable_alloc(&test_fd_obj_type, &obj_a, test_fd_obj_init,
                          test_fd_obj_deinit);
    zassert_true(fd >= 0, "Failed to allocate FD");

    /* Get object type */
    type = z_fdtable_get_obj_type(fd);
    zassert_equal(type, &test_fd_obj_type, "Did not get correct object type");

    /* Test with invalid FD */
    type = z_fdtable_get_obj_type(-1);
    zassert_is_null(type, "Got object type for invalid FD");

    /* Free the FD */
    z_fdtable_free(fd);
}

/* Test case: Get object type and object pointer */
ZTEST(fdtable_tests, test_fdtable_get_obj_and_type)
{
    int fd;
    void *obj_ptr;
    const struct k_obj_type *type;

    /* Allocate an FD */
    fd = z_fdtable_alloc(&test_fd_obj_type, &obj_a, test_fd_obj_init,
                          test_fd_obj_deinit);
    zassert_true(fd >= 0, "Failed to allocate FD");

    /* Get object and type */
    obj_ptr = z_fdtable_object_get_and_type(fd, &type);
    zassert_equal(obj_ptr, &obj_a, "Did not get correct object");
    zassert_equal(type, &test_fd_obj_type, "Did not get correct object type");
    z_fdtable_object_put(fd); /* Release reference */

    /* Test with invalid FD */
    obj_ptr = z_fdtable_object_get_and_type(-1, &type);
    zassert_is_null(obj_ptr, "Got object for invalid FD");
    zassert_is_null(type, "Got object type for invalid FD");
    z_fdtable_object_put(-1); /* Release reference */

    /* Free the FD */
    z_fdtable_free(fd);
}

