static void *fdtable_tests_setup(void)
{
    /* Reset dummy values for objects */
    obj_a.dummy = 0;
    obj_b.dummy = 0;
    obj_c.dummy = 0;

    /* Ensure fdtable is clean before each test */
    z_fdtable_clear();

    return NULL;
}

ZTEST_SUITE(fdtable_tests, NULL, fdtable_tests_setup, NULL, NULL, NULL);
